import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 12 章 数据与表格：清洗、分析与图表（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第12章 数据与表格：清洗、分析与图表（易懂版）.md","filePath":"easy/第12章 数据与表格：清洗、分析与图表（易懂版）.md"}'),s={name:"easy/第12章 数据与表格：清洗、分析与图表（易懂版）.md"};function l(n,t,i,u,h,d){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-12-章-数据与表格-清洗、分析与图表-易懂版" tabindex="-1">第 12 章 数据与表格：清洗、分析与图表（易懂版） <a class="header-anchor" href="#第-12-章-数据与表格-清洗、分析与图表-易懂版" aria-label="Permalink to &quot;第 12 章 数据与表格：清洗、分析与图表（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 12 章 数据与表格：清洗、分析与图表（完整版）](../../bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 数据与表格：清洗、分析与图表.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>脏乱差的表格交给 AI——清洗、分析、出图，一条龙。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>拿到一张乱糟糟的 Excel，就像拿到一堆没洗的菜。我先把菜<strong>洗干净（清洗）</strong>，再按你要的口味<strong>做成菜（分析）</strong>，最后**摆盘（图表）**给你看。</p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>清洗</strong>：去掉重复行、修正格式（日期乱七八糟？数字带单位？）、补缺失值——先让数据&quot;能看&quot;。</li><li><strong>分析</strong>：按你的问题算——求和、占比、趋势、对比、排名……<strong>先告诉我你想回答什么问题</strong>。</li><li><strong>出图</strong>：转成柱状图/折线图/饼图，放进报告或 Excel。</li></ol><h2 id="关键一步-先定义-干净" tabindex="-1">关键一步：先定义&quot;干净&quot; <a class="header-anchor" href="#关键一步-先定义-干净" aria-label="Permalink to &quot;关键一步：先定义&quot;干净&quot;&quot;">​</a></h2><p>跟我说清楚：</p><ul><li><strong>哪些列是重点</strong>（比如：日期、金额、地区）；</li><li><strong>&quot;脏&quot;长什么样</strong>（重复？空值？格式乱？）；</li><li><strong>清洗规则</strong>（重复的留哪条？空值填 0 还是删掉？）。</li></ul><p>规则越清楚，清洗越不会误伤。</p><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;<code>销售表.xlsx</code> 里日期格式很乱，还有重复行。帮我去重（保留最新一条），日期统一成 <code>2026-08-01</code> 格式，再按月份汇总销售额，做成柱状图。&quot;</p><p><strong>你会看到</strong>：我先报告发现的问题（几行重复、几处格式乱）→ 清洗 → 汇总 → 出图 → 交付。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 数据里混着&quot;备注&quot;就让我算——<strong>先把脏数据清干净再分析</strong>；</li><li>❌ 不问问题就让分析——<strong>没有问题的分析，只会给一堆没用的数</strong>；</li><li>❌ 清洗规则含糊——&quot;把重复的去掉&quot;——<strong>留哪条？说清楚！</strong></li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>数据处理 = 先定义干净 + 清洗 + 回答你的问题 + 图表呈现。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>打开一个乱表格，说一句话给我：<strong>&quot;这张表哪里最让你头疼？&quot;</strong> 那通常就是清洗的第一个任务。</p><p>👉 [下一章：知识管理，让记忆可复用（易懂版）](第13章 知识管理：让记忆可复用（易懂版）.md)</p>',21)])])}const g=o(s,[["render",l]]);export{_ as __pageData,g as default};
